('secret-cultist', 'cthulhu', null, null, 'citacao', 'Vivemos numa ilha plácida de ignorância, no meio de mares negros de infinito.', 'H. P. Lovecraft, O Chamado de Cthulhu (1928)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, 'abertura', 'citacao', 'A oeste de Arkham as colinas se erguem selvagens, e há vales com matas fundas que nenhum machado jamais cortou.', 'H. P. Lovecraft, A Cor que Caiu do Espaço (1927)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, null, 'citacao', 'Infeliz é aquele a quem as lembranças da infância só trazem medo e tristeza.', 'H. P. Lovecraft, O Estranho (1926)', '2026-11-09'),
('secret-cultist', 'cthulhu', 'dagon', 'abertura', 'citacao', 'Escrevo isto sob uma pressão mental considerável, pois esta noite já não existirei.', 'H. P. Lovecraft, Dagon (1919)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, 'abertura', 'citacao', 'Quem procura o horror frequenta lugares estranhos e distantes.', 'H. P. Lovecraft, A Imagem na Casa (1921)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, 'eliminacao', 'citacao', 'Seu tolo, o Warren está MORTO!', 'H. P. Lovecraft, O Depoimento de Randolph Carter (1920)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, null, 'citacao', 'Há na terra de Mnar um grande lago parado, que nenhum rio alimenta e de onde nenhum rio sai.', 'H. P. Lovecraft, A Maldição que Caiu sobre Sarnath (1920)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, null, 'citacao', 'Em Ulthar, que fica além do rio Skai, nenhum homem pode matar um gato.', 'H. P. Lovecraft, Os Gatos de Ulthar (1920)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, 'ato3', 'citacao', 'Ao longe, um latido fraco, como o de um cão gigantesco.', 'H. P. Lovecraft, O Cão (1924, adaptado)', '2026-11-09'),
('secret-cultist', 'cthulhu', null, 'ato3', 'citacao', 'Tekeli-li! Tekeli-li!', 'H. P. Lovecraft, Nas Montanhas da Loucura (1936)', '2026-11-09'),
('secret-cultist', 'cthulhu', 'cthulhu', 'ato3', 'citacao', 'Iä! Iä! Cthulhu fhtagn!', 'H. P. Lovecraft, O Chamado de Cthulhu (1928)', '2026-11-09'),
('secret-cultist', 'cthulhu', 'hastur', null, 'citacao', 'Não sobre nós, ó Rei, não sobre nós!', 'Robert W. Chambers, O Rei de Amarelo (1895)', '2026-11-09'),
('secret-cultist', 'cthulhu', 'hastur', 'ato2', 'citacao', 'A canção que as Híades cantam, onde os farrapos do Rei esvoaçam, há de morrer sem ser ouvida na Carcosa sombria.', 'Robert W. Chambers, O Rei de Amarelo (1895), Canção de Cassilda', '2026-11-09'),
('secret-cultist', 'cthulhu', 'hastur', null, 'citacao', 'Há muitos tipos de morte: em alguns o corpo fica; em outros ele some junto com o espírito.', 'Ambrose Bierce, Um Habitante de Carcosa (1886)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'eliminacao', 'citacao', 'E as Trevas e a Ruína e a Morte Rubra tiveram domínio sem limite sobre todos.', 'Edgar Allan Poe, A Máscara da Morte Rubra (1842)', '2026-11-09'),
('secret-cultist', 'literatura', null, null, 'citacao', 'Disse o corvo: “Nunca mais.”', 'Edgar Allan Poe, O Corvo (1845)', '2026-11-09'),
('secret-cultist', 'literatura', null, null, 'citacao', 'Tudo o que vemos ou parecemos não passa de um sonho dentro de um sonho.', 'Edgar Allan Poe, Um Sonho dentro de um Sonho (1849)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'investigacao', 'citacao', 'Era a batida do seu coração horrendo!', 'Edgar Allan Poe, O Coração Delator (1843)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'abertura', 'citacao', 'Durante todo um dia escuro, sombrio e sem som, no outono do ano.', 'Edgar Allan Poe, A Queda da Casa de Usher (1839)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'eliminacao', 'citacao', 'Pelo amor de Deus, Montresor!', 'Edgar Allan Poe, O Barril de Amontillado (1846)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'abertura', 'citacao', 'Bem-vindo à minha casa! Entre livremente, e por vontade própria!', 'Bram Stoker, Drácula (1897)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'ato2', 'citacao', 'Escutem, os filhos da noite. Que música eles fazem!', 'Bram Stoker, Drácula (1897)', '2026-11-09'),
('secret-cultist', 'literatura', null, null, 'citacao', 'Cuidado, pois não tenho medo, e por isso sou poderoso.', 'Mary Shelley, Frankenstein (1818)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'abertura', 'citacao', 'Quem é este que vem?', 'M. R. James, Oh, Assobie e Eu Irei até Você (1904), a inscrição do apito', '2026-11-09'),
('secret-cultist', 'literatura', null, 'ato2', 'citacao', 'Pelo comichão dos meus polegares, algo malvado vem para cá.', 'William Shakespeare, Macbeth (1623)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'ato3', 'citacao', 'Dobra, dobra, labuta e mágoa; queime o fogo e ferva a água.', 'William Shakespeare, Macbeth (1623)', '2026-11-09'),
('secret-cultist', 'literatura', null, null, 'citacao', 'Há mais coisas entre o céu e a terra, Horácio, do que sonha a sua filosofia.', 'William Shakespeare, Hamlet (1603)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'ato3', 'citacao', 'Agora é a hora mais enfeitiçada da noite, quando os cemitérios bocejam.', 'William Shakespeare, Hamlet (1603)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'investigacao', 'citacao', 'Há algo de podre no reino da Dinamarca.', 'William Shakespeare, Hamlet (1603)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'abertura', 'citacao', 'No meio do caminho da nossa vida, eu me achei numa floresta escura.', 'Dante Alighieri, Inferno, canto I (tradução de Longfellow, 1867)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'fim-F', 'citacao', 'Abandonai toda a esperança, vós que entrais.', 'Dante Alighieri, Inferno, canto III (tradução de Longfellow, 1867)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'fim-F', 'citacao', 'Melhor reinar no Inferno do que servir no Céu.', 'John Milton, O Paraíso Perdido (1667)', '2026-11-09'),
('secret-cultist', 'literatura', null, null, 'citacao', 'A mente é o seu próprio lugar, e nela pode fazer do Inferno um Céu e do Céu um Inferno.', 'John Milton, O Paraíso Perdido (1667)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'eliminacao', 'citacao', 'Vês?! Ninguém assistiu ao formidável enterro de tua última quimera.', 'Augusto dos Anjos, Versos Íntimos, em Eu (1912)', '2026-11-09'),
('secret-cultist', 'literatura', null, 'investigacao', 'citacao', 'O beijo, amigo, é a véspera do escarro, a mão que afaga é a mesma que apedreja.', 'Augusto dos Anjos, Versos Íntimos, em Eu (1912)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'investigacao', 'citacao', 'Guardai-vos dos falsos profetas, que vêm a vós vestidos de ovelhas, mas por dentro são lobos devoradores.', 'Bíblia, Mateus 7:15 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'rejeicao', 'citacao', 'A mão daquele que me trai está comigo à mesa.', 'Bíblia, Lucas 22:21 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'rejeicao', 'citacao', 'Em verdade vos digo que um de vós me trairá.', 'Bíblia, Mateus 26:21 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'investigacao', 'citacao', 'Quando ele falar com doçura, não acredites, porque há sete abominações no seu coração.', 'Bíblia, Provérbios 26:25 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'investigacao', 'citacao', 'O próprio Satanás se transfigura em anjo de luz.', 'Bíblia, 2 Coríntios 11:14 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'eliminacao', 'citacao', 'Até o meu amigo íntimo, em quem eu confiava, levantou contra mim o calcanhar.', 'Bíblia, Salmos 41:9 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'ato3', 'citacao', 'Olhei, e eis um cavalo amarelo, e o que estava montado nele chamava-se Morte, e o Inferno o seguia.', 'Bíblia, Apocalipse 6:8 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'ato2', 'citacao', 'O vosso adversário, o diabo, anda em derredor, como leão que ruge, buscando a quem possa tragar.', 'Bíblia, 1 Pedro 5:8 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, null, 'citacao', 'Também os demônios creem, e estremecem.', 'Bíblia, Tiago 2:19 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, null, 'citacao', 'De rodear a terra, e de passear por ela.', 'Bíblia, Jó 1:7 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'astarote', null, 'citacao', 'Quem aumenta o conhecimento aumenta a dor.', 'Bíblia, Eclesiastes 1:18 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'mamon', null, 'citacao', 'O amor ao dinheiro é a raiz de todos os males.', 'Bíblia, 1 Timóteo 6:10 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'dagon', null, 'citacao', 'Os príncipes dos filisteus se reuniram para oferecer um grande sacrifício a Dagom, o seu deus.', 'Bíblia, Juízes 16:23 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'dagon', 'fim-L', 'citacao', 'Dagom estava caído com o rosto em terra diante da arca do Senhor.', 'Bíblia, 1 Samuel 5:4 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'baal', null, 'citacao', 'Ide e consultai Baal-Zebube, deus de Ecrom.', 'Bíblia, 2 Reis 1:2 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'moloque', null, 'citacao', 'Edificaram os altos de Baal, para fazerem passar pelo fogo os seus filhos e as suas filhas a Moloque.', 'Bíblia, Jeremias 32:35 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'hydra', null, 'citacao', 'Naquele dia o Senhor castigará o leviatã, a serpente veloz, o dragão que está no mar.', 'Bíblia, Isaías 27:1 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'marduque', null, 'citacao', 'As feras do deserto repousarão ali, e as suas casas se encherão de corujas, e os sátiros pularão ali.', 'Bíblia, Isaías 13:21 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'marduque', 'fim-L', 'citacao', 'Caiu, caiu a grande Babilônia, e se tornou morada de demônios.', 'Bíblia, Apocalipse 18:2 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'marduque', 'ato3', 'citacao', 'MISTÉRIO, A GRANDE BABILÔNIA, A MÃE DAS PROSTITUIÇÕES E ABOMINAÇÕES DA TERRA.', 'Bíblia, Apocalipse 17:5 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', 'marduque', 'ato2', 'citacao', 'Apareceram uns dedos de mão de homem, e escreviam na parede do palácio do rei.', 'Bíblia, Daniel 5:5 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'abertura', 'citacao', 'E a terra era sem forma e vazia.', 'Bíblia, Gênesis 1:2 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, 'fim-L', 'citacao', 'Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as ciladas do diabo.', 'Bíblia, Efésios 6:11 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, null, 'citacao', 'Não terás outros deuses diante de mim.', 'Bíblia, Êxodo 20:3 (King James, 1611)', '2026-11-09'),
('secret-cultist', 'biblia', null, null, 'citacao', 'Azazel ensinou os homens a fazer espadas e facas, escudos e couraças.', 'Livro de Enoque 8:1 (tradução de R. H. Charles, 1912)', '2026-11-09'),
('secret-cultist', 'demonologia', 'baal', null, 'citacao', 'O primeiro espírito principal é um rei que governa no Oriente, chamado Bael.', 'A Chave Menor de Salomão, Goécia (tradução de Mathers, 1904)', '2026-11-09'),
('secret-cultist', 'demonologia', null, null, 'citacao', 'Belial foi criado logo depois de Lúcifer.', 'A Chave Menor de Salomão, Goécia (adaptado da tradução de Mathers, 1904)', '2026-11-09')
